const currentPolicies = $('Query RLS Policies via API').all().map(i => i.json);
const expectedConfig = $('Read Expected Config').all().map(i => i.json);

const mismatches = [];
const missing = [];
const extra = [];

// Build lookup maps
const currentMap = {};
currentPolicies.forEach(p => {
  const key = `${p.table_name}:${p.policy_name}`;
  currentMap[key] = p;
});

const expectedMap = {};
expectedConfig.forEach(e => {
  const key = `${e.table_name}:${e.policy_name}`;
  expectedMap[key] = e;
});

// Check expected vs current
for (const [key, expected] of Object.entries(expectedMap)) {
  if (!currentMap[key]) {
    missing.push({ key, expected });
  } else {
    const current = currentMap[key];
    if (current.command !== expected.command || 
        current.permissive !== expected.permissive) {
      mismatches.push({ key, expected, current });
    }
  }
}

// Check for unexpected policies
for (const key of Object.keys(currentMap)) {
  if (!expectedMap[key]) {
    extra.push({ key, policy: currentMap[key] });
  }
}

const hasIssues = mismatches.length > 0 || missing.length > 0 || extra.length > 0;

return [{
  json: {
    status: hasIssues ? 'MISMATCH_DETECTED' : 'ALL_CLEAR',
    total_current_policies: currentPolicies.length,
    total_expected_policies: expectedConfig.length,
    mismatches: mismatches,
    missing_policies: missing,
    extra_policies: extra,
    mismatch_count: mismatches.length,
    missing_count: missing.length,
    extra_count: extra.length,
    has_issues: hasIssues,
    audit_timestamp: new Date().toISOString()
  }
}];

